'use strict';
/* public/js/82-patrol.js -- shared clock/curfew, police patrols, Madame Zeroni. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- curfew + police: one clock every camper shares; each camper gets their own patrol ---------- */
/* the night is split in two: police until 01:00, then Madame Zeroni until dawn */
const CYCLE=12*60*1000,DAYMS=9.5*60*1000,NIGHT_SPLIT=DAYMS+(CYCLE-DAYMS)/2;
const CLK={off:0,paused:false,pt:0};
const wrapT=t=>((t%CYCLE)+CYCLE)%CYCLE;
function clockT(){return CLK.paused?CLK.pt:wrapT(Date.now()+CLK.off)}
function nightF(){const t=clockT();if(t<DAYMS)return sm((t-(DAYMS-50000))/50000);return t>CYCLE-25000?1-sm((t-(CYCLE-25000))/25000):1}
function hourOf(t){return t<DAYMS?6+t/DAYMS*14:(20+(t-DAYMS)/(CYCLE-DAYMS)*10)%24}
function tAtHour(h){h=((h%24)+24)%24;return h>=6&&h<20?(h-6)/14*DAYMS:DAYMS+((h<6?h+24:h)-20)/10*(CYCLE-DAYMS)}
function clockText(){const h=hourOf(clockT()),hh=Math.floor(h)%24,mi=Math.floor((h%1)*60);return String(hh).padStart(2,'0')+':'+String(mi).padStart(2,'0')}

/* hidden admin clock: type "sploosh" in game. On a server it only opens for the host, and the server ignores clock changes from anyone else. */
function setClock(m){if(!m||typeof m!=='object')return;CLK.off=num(m.off,-1e13,1e13,0);CLK.paused=m.paused===true;CLK.pt=wrapT(num(m.pt,0,CYCLE,0));renderAdmin()}
function applyClock(c){Object.assign(CLK,c);wsSend({t:'clock',off:CLK.off,paused:CLK.paused,pt:CLK.pt});renderAdmin()}
function jumpTo(t){t=wrapT(t);if(CLK.paused)applyClock({pt:t});else applyClock({off:t-Date.now()})}
function toggleAdmin(){const el=$('#admin');if(el.hidden&&net.ws&&net.ws.readyState===1&&!net.host)return;el.hidden=!el.hidden;if(!el.hidden){releaseLock();renderAdmin()}}
function renderAdmin(){if($('#admin').hidden)return;$('#admT').textContent=clockText();$('#admS').textContent=CLK.paused?'paused':CLK.off?'(changed)':'(real clock)';$('#admPause').textContent=CLK.paused?'Resume time':'Pause time'}
$('#admin').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
  if(d.h)jumpTo(tAtHour(+d.h));else if(d.c)jumpTo(DAYMS-59000);else if(d.d)jumpTo(tAtHour(hourOf(clockT())+(+d.d)));
  else if(d.a){if(online())wsSend({t:'admin',a:d.a});else{setRun({day:RUN.day,bank:0});saveRun()}}
  else if(b.id==='admPause'){if(CLK.paused)applyClock({paused:false,off:CLK.pt-Date.now()});else applyClock({paused:true,pt:clockT()})}
  else if(b.id==='admReal')applyClock({paused:false,off:0,pt:0});
  b.blur()});
$('#admClose').onclick=toggleAdmin;
setInterval(renderAdmin,250);
function fmtT(s){s=Math.max(0,Math.floor(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function campDist(x,z){return Math.hypot(Math.max(-40-x,0,x-30),Math.max(27-z,0,z-56))}
const NIGHT_SKY=new T.Color(0.035,0.045,0.1),NIGHT_FOG=new T.Color(0x07090f),SKY_T=new T.Color(),FOG_T=new T.Color();
const stars=(()=>{const n=1500,p=new Float32Array(n*3);for(let i=0;i<n;i++){const u=Math.random()*Math.PI*2,v=Math.acos(Math.random()*0.95);p[i*3]=Math.sin(v)*Math.cos(u)*850;p[i*3+1]=Math.cos(v)*850;p[i*3+2]=Math.sin(v)*Math.sin(u)*850}
  const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(p,3));const s=new T.Points(g,new T.PointsMaterial({color:0xffffff,size:1.6,sizeAttenuation:false,transparent:true,opacity:0,fog:false,depthWrite:false}));s.frustumCulled=false;scene.add(s);return s})();
/* A police officer on foot (the night patrol, see stepCop in sim.js): dark uniform, campaign hat, and a flashlight whose
   visible cone matches the light that can actually spot you (SIM.COP_RANGE / COP_HALF_ANGLE). The array is still
   called `trucks` because the server, minimap and logs already use that name for the police. */
const COP_LOOKS=[0xe0b08a,0x8a5a3c,0xc68a5e,0x6b4a35];
function makeTruck(i){
  const p=makePerson({suit:0x1d2a44,shirt:0x9fb3c8,skin:COP_LOOKS[i%COP_LOOKS.length],hat:'cowboy',shovel:false});
  const torch=box(0.07,0.07,0.26,0x2a2a2a);torch.position.set(0,-0.5,0.12);p.armR.add(torch);   // flashlight in the right hand
  const spot=new T.SpotLight(0xfff0cc,0,SIM.CURFEW.copRange,SIM.CURFEW.copHalf,0.55,1);spot.position.set(0.3,1.25,0.35);spot.target.position.set(0.3,0,12);p.g.add(spot,spot.target);
  const beam=new T.Mesh(new T.BufferGeometry(),new T.MeshBasicMaterial({color:0xfff0cc,transparent:true,opacity:0.045,blending:T.AdditiveBlending,depthWrite:false,side:T.DoubleSide,fog:false}));beam.position.copy(spot.position);p.g.add(beam);
  p.g.position.y=-200;scene.add(p.g);
  const L=makeLabel(p.g,'Police','npc');
  return{g:p.g,p,L,spot,beam,beamKey:'',x:0,z:0,h:0,mode:'patrol',active:false};
}
/* the flashlight's visible cone: rebuilt when the Curfew tab changes its reach or width */
function copBeamGeometry(){const C=SIM.CURFEW,g=new T.ConeGeometry(Math.tan(C.copHalf)*C.copRange,C.copRange,16,1,true);g.translate(0,-C.copRange/2,0);g.rotateX(-Math.PI/2+0.1);return g}
const COP_LIGHT=2.2;   // flashlight SpotLight intensity (x the Curfew tab's brightness)
// One per officer. Four are made up front (the default patrol) so their lights are in the shaders from the start;
// more are added if the Curfew tab asks for a bigger patrol.
const trucks=[0,1,2,3].map(makeTruck);
const CUR={phase:clockT()<DAYMS?'day':'night',warned:clockT()>DAYMS-60000,hunter:null,half:null,msgT:0};
function siren(){for(let i=0;i<3;i++)setTimeout(()=>tone(450,1.4,'sawtooth',0.07,900),i*1500)}
/* trucks and Zeroni are moved by the shared rules in sim.js (on the server, or right here when you play solo). This just draws them. */
function showTruck(tk,st,dt){
  if(!st){if(tk.active){tk.active=false;tk.g.position.y=-200;tk.spot.intensity=0;tk.beam.visible=false}return}
  if(!tk.active){tk.active=true;tk.x=st.x;tk.z=st.z;tk.h=st.h}
  const k=Math.min(1,dt*8),px=tk.x,pz=tk.z;tk.x+=(st.x-tk.x)*k;tk.z+=(st.z-tk.z)*k;let dh=st.h-tk.h;dh=Math.atan2(Math.sin(dh),Math.cos(dh));tk.h+=dh*k;tk.mode=st.chase?'chase':'patrol';
  const moving=Math.hypot(tk.x-px,tk.z-pz)/Math.max(dt,1e-3)>0.3;
  tk.g.position.set(tk.x,groundAt(tk.x,tk.z),tk.z);tk.g.rotation.y=tk.h+Math.PI;   // sim heading faces -z at 0; people models face +z
  animPerson(tk.p,st.chase?4:moving?1:0,dt);
  tk.p.armR.rotation.x=-1.25;   // flashlight held out in front
  const C=SIM.CURFEW,key=C.copRange+','+C.copHalf,pow=tuneOr('curfew.copLight',1),on=nightF()>0.3;
  if(key!==tk.beamKey){tk.beamKey=key;tk.beam.geometry.dispose();tk.beam.geometry=copBeamGeometry();tk.spot.distance=C.copRange;tk.spot.angle=C.copHalf}
  tk.spot.intensity=on?COP_LIGHT*pow:0;tk.beam.visible=on&&pow>0;tk.beam.material.opacity=0.045*Math.min(pow,3);
}

/* ---------- Madame Zeroni: she hunts anyone still out on the lake after 01:00 ---------- */
const ZER_LINE='yo carry me up dat mountain bruh, I gave you dat piggy bruh';
const ZER=(()=>{
  const g=new T.Group(),up=new T.Group();
  const robeM=new T.MeshStandardMaterial({color:0x26301f,flatShading:true,roughness:1,emissive:0x0b1408});
  const skinM=new T.MeshStandardMaterial({color:0x9aae8c,flatShading:true,roughness:1,emissive:0x1c2e14});
  const hairM=new T.MeshStandardMaterial({color:0xcfd3c2,flatShading:true,roughness:1});
  const pigM=new T.MeshStandardMaterial({color:0xf2a0b0,flatShading:true,roughness:0.9});
  const eyeM=new T.MeshBasicMaterial({color:0xff3a1a}),dark=new T.MeshBasicMaterial({color:0x050505});
  const add=(p,geo,m,x,y,z)=>{const o=new T.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;p.add(o);return o};
  add(g,new T.ConeGeometry(0.85,2,9),robeM,0,1,0);
  for(let i=0;i<9;i++){const a=i/9*Math.PI*2;add(g,new T.ConeGeometry(0.16,0.55,4),robeM,Math.sin(a)*0.8,0.05,Math.cos(a)*0.8).rotation.x=Math.PI}
  up.position.set(0,1.75,0);up.rotation.x=0.45;g.add(up);
  add(up,new T.BoxGeometry(0.9,0.35,0.5),robeM,0,0.1,0);
  add(up,new T.SphereGeometry(0.3,8,6),skinM,0,0.55,0.12).scale.set(0.9,1.15,0.95);
  for(const x of[-0.1,0.1])add(up,new T.SphereGeometry(0.06,6,4),eyeM,x,0.6,0.39);
  add(up,new T.BoxGeometry(0.14,0.14,0.04),dark,0,0.38,0.38);
  for(let i=0;i<12;i++){const a=Math.PI*0.45+i/11*Math.PI*1.1;add(up,new T.BoxGeometry(0.05,0.8,0.05),hairM,Math.sin(a)*0.27,0.4,0.12+Math.cos(a)*0.27)}
  const arms=[-1,1].map(s=>{const a=new T.Group();a.position.set(s*0.45,0.1,0);up.add(a);
    add(a,new T.CylinderGeometry(0.06,0.05,1.1,5),skinM,0,0,0.55).rotation.x=Math.PI/2;
    for(const f of[-0.06,0,0.06])add(a,new T.ConeGeometry(0.025,0.22,4),dark,f,0,1.18).rotation.x=Math.PI/2;
    return a});
  // she's still holding the piggy
  const pig=new T.Group();pig.position.set(0,0.12,1.05);arms[0].add(pig);
  add(pig,new T.BoxGeometry(0.3,0.26,0.45),pigM,0,0,0);add(pig,new T.BoxGeometry(0.22,0.2,0.18),pigM,0,0.05,0.28);
  add(pig,new T.BoxGeometry(0.1,0.07,0.05),M(0xd97a8e),0,0.03,0.39);for(const x of[-0.07,0.07])add(pig,new T.BoxGeometry(0.06,0.08,0.02),pigM,x,0.18,0.25);
  const light=new T.PointLight(0x7dff6a,0,16);light.position.set(0,1.8,0.4);g.add(light);
  g.scale.setScalar(1.45);g.visible=false;scene.add(g);
  return{g,arms,eyeM,light,L:makeLabel(g,'Madame Zeroni','',3.5),x:0,z:0,active:false,talk:0,blink:10,hb:0};
})();
function setZeroni(on,st){ZER.active=on;ZER.g.visible=on;ZER.light.intensity=on?1.6:0;if(on){ZER.x=st.x;ZER.z=st.z;ZER.hb=0}else{ZER.L.b.textContent='';ZER.L.sayUntil=0;try{speechSynthesis.cancel()}catch(e){}}}
function zeroniSting(v){v=v||1;tone(70,2.5,'sawtooth',0.1*v,35);noise(1.5,600,0.5,0.2*v,'lowpass');tone(1760,1.6,'sine',0.03*v,1700)}
function zeroniTalk(d){if(d>95)return;say(ZER.L,ZER_LINE,5000);noise(1.2,1400,3,0.12*clamp(1.2-d/80,0.2,1));speak(ZER_LINE,{pitch:0.1,rate:0.8,vol:clamp(1.1-d/60,0.2,1),cut:true})}
function jumpScare(){const el=$('#scare');el.classList.add('on');tone(140,0.9,'sawtooth',0.16,60);noise(0.7,900,0.6,0.5);setTimeout(()=>el.classList.remove('on'),420)}
function showZeroni(st,dt){
  if(!!st!==ZER.active)setZeroni(!!st,st);if(!st)return;
  const now=performance.now()/1000,k=Math.min(1,dt*8),ox=ZER.x,oz=ZER.z;
  if(Math.hypot(st.x-ZER.x,st.z-ZER.z)>6){ZER.x=st.x;ZER.z=st.z}else{ZER.x+=(st.x-ZER.x)*k;ZER.z+=(st.z-ZER.z)*k}
  const mvx=ZER.x-ox,mvz=ZER.z-oz,dragging=st.drag!=null;
  // she faces whoever she's after; while dragging someone she faces where she's going
  let fx=P.x,fz=P.z;if(st.tgt!=null&&st.tgt!==myId()){const R=remotes.get(st.tgt);if(R){fx=R.p.g.position.x;fz=R.p.g.position.z}}
  const ry=dragging&&Math.hypot(mvx,mvz)>1e-4?Math.atan2(mvx,mvz):Math.atan2(fx-ZER.x,fz-ZER.z);
  const d=Math.hypot(P.x-ZER.x,P.z-ZER.z);
  if(!S.ko){ZER.hb-=dt;if(d<40&&ZER.hb<=0){ZER.hb=0.32+d/40*0.9;tone(62,0.14,'sine',0.3,40);setTimeout(()=>tone(55,0.16,'sine',0.24,36),150)}}
  if(dragging&&st.drag===myId()&&S.ko){P.x=ZER.x-Math.sin(ry)*1.1;P.z=ZER.z-Math.cos(ry)*1.1;P.y=groundAt(P.x,P.z)}
  ZER.g.position.set(ZER.x,groundAt(ZER.x,ZER.z)+0.3+Math.sin(now*2.2)*0.15,ZER.z);ZER.g.rotation.y=ry;
  ZER.arms.forEach((a,i)=>a.rotation.x=dragging?0.6:-0.35+Math.sin(now*5+i*2)*0.18);
  const fl=Math.random()<0.06;ZER.light.intensity=fl?0.3:1.6;ZER.eyeM.color.setHex(fl?0x330000:0xff3a1a);
}

/* spoken lines (browser text-to-speech) */
function speak(text,o){if(muted||!('speechSynthesis' in window))return;try{const u=new SpeechSynthesisUtterance(text);u.pitch=o.pitch;u.rate=o.rate;u.volume=clamp(o.vol,0,1);
  const vs=speechSynthesis.getVoices(),re=o.male?/david|mark|guy|male/i:/zira|susan|hazel|samantha|female/i;const v=vs.find(v=>/^en/i.test(v.lang)&&re.test(v.name))||vs.find(v=>/^en/i.test(v.lang));if(v)u.voice=v;
  if(o.cut)speechSynthesis.cancel();speechSynthesis.speak(u)}catch(e){}}

/* night sound loops: police siren + engine, Zeroni drone + whisper. Volume follows distance. */
const LOOP={};
function loops(){if(!AC)return false;if(LOOP.ok)return true;LOOP.ok=true;
  const so=AC.createOscillator();so.type='sawtooth';so.frequency.value=760;
  LOOP.lfo=AC.createOscillator();LOOP.lfo.frequency.value=0.45;const lg=AC.createGain();lg.gain.value=320;LOOP.lfo.connect(lg).connect(so.frequency);
  const sf=AC.createBiquadFilter();sf.type='lowpass';sf.frequency.value=2200;LOOP.siren=AC.createGain();LOOP.siren.gain.value=0;so.connect(sf).connect(LOOP.siren).connect(fxBus);so.start();LOOP.lfo.start();
  const eo=AC.createOscillator();eo.type='sawtooth';eo.frequency.value=48;const ef=AC.createBiquadFilter();ef.type='lowpass';ef.frequency.value=180;LOOP.engine=AC.createGain();LOOP.engine.gain.value=0;eo.connect(ef).connect(LOOP.engine).connect(fxBus);eo.start();
  const df=AC.createBiquadFilter();df.type='lowpass';df.frequency.value=260;LOOP.drone=AC.createGain();LOOP.drone.gain.value=0;df.connect(LOOP.drone).connect(fxBus);
  for(const f of[55,58.3,82.4]){const o=AC.createOscillator();o.type='sawtooth';o.frequency.value=f;o.connect(df);o.start()}
  const wn=AC.createBufferSource();wn.buffer=noiseBuf;wn.loop=true;const wf=AC.createBiquadFilter();wf.type='bandpass';wf.frequency.value=1700;wf.Q.value=4;LOOP.whisper=AC.createGain();LOOP.whisper.gain.value=0;wn.connect(wf).connect(LOOP.whisper).connect(fxBus);wn.start();
  return true}
function updateNightSound(){
  if(!loops())return;const at=AC.currentTime;
  let pd=1e9,chase=false;for(const tk of trucks)if(tk.active){pd=Math.min(pd,Math.hypot(tk.x-P.x,tk.z-P.z));if(tk.mode==='chase')chase=true}
  const pv=Math.pow(clamp(1-pd/140,0,1),1.5),zv=ZER.active?Math.pow(clamp(1-Math.hypot(ZER.x-P.x,ZER.z-P.z)/90,0,1),1.3):0;
  LOOP.siren.gain.setTargetAtTime(0,at,0.25);LOOP.engine.gain.setTargetAtTime(0,at,0.25);   // officers walk: no car engine or siren loopLOOP.lfo.frequency.setTargetAtTime(chase?2.6:0.45,at,0.3);
  LOOP.drone.gain.setTargetAtTime(zv*0.16,at,0.3);LOOP.whisper.gain.setTargetAtTime(zv*0.05,at,0.3);
}

function hunterToast(h,was){
  if(h==='police'){tone(200,1.2,'sawtooth',0.08,120);toast(was?'The police patrol is still out there.':'Curfew. Officers with flashlights are walking the lake. Stay out of their lights and the tower beams, or get back through the gate.','bad',6000)}
  else if(h==='zeroni'){zeroniSting();toast(was?'The police head back to town. Then the wind stops. Madame Zeroni is coming. RUN FOR CAMP.':'Madame Zeroni is out on the lake, and she wants a ride up the mountain. RUN FOR CAMP.','bad',6500)}
}
function updateCurfew(dt){
  $('#hud').classList.toggle('zone-away',!!ZONE_H);   // curfew rows hide outside the lake (game.css)
  const t=clockT(),night=t>=DAYMS,out=!inCamp(P.x,P.z);
  stepSoloMonsters(dt);stepSoloDirector(dt);while(trucks.length<MONV.trucks.length)trucks.push(makeTruck(trucks.length));
  trucks.forEach((tk,i)=>showTruck(tk,MONV.trucks[i],dt));showZeroni(MONV.zer,dt);updateNightSound();
  if(!night){
    if(CUR.phase==='night'){CUR.phase='day';if(CUR.hunter)toast(CUR.hunter==='zeroni'?'Dawn. Madame Zeroni fades away with the sunrise.':'Dawn. The police head back to town.','good',4000);CUR.hunter=null}
    if(t<DAYMS-60000)CUR.warned=false;
    else if(!CUR.warned){CUR.warned=true;siren();toast('SIREN: curfew in one minute. Get back inside the camp fence!','bad',6000)}
    return;
  }
  const half=t<NIGHT_SPLIT?'police':'zeroni';
  if(CUR.phase==='day'){CUR.phase='night';CUR.half=half;soloEndOfDay();if(!out)toast('Curfew. Lights out, campers.','',3500)}
  else if(CUR.half!==half){CUR.half=half;if(half==='zeroni'&&!out){zeroniSting(0.5);toast('01:00. The police go home. Out on the lake, someone is asking for a ride up the mountain…','',5000)}}
  const h=MONV.zer?'zeroni':MONV.trucks.length?'police':null,want=out?h:null;   // Zeroni first: the officers are out all night
  if(want!==CUR.hunter){const was=CUR.hunter;CUR.hunter=want;if(want)hunterToast(want,was);else if(was&&!out&&performance.now()-S.respawnAt>1500)toast(was==='zeroni'?'You made it inside the fence. Madame Zeroni can\'t cross it. She waits out there…':'You made it back inside the fence. The police won\'t follow you into camp.','good',4000)}
}

/* shared monsters: the server sends where they are; solo play runs the same rules here */
const MONL={trucks:[],zer:null},MONV={trucks:[],zer:null};
function myId(){return online()?net.id:'me'}
function meSim(){const dep=baseH(P.x,P.z)-P.y;return{id:myId(),x:S.inTown?0:P.x,z:S.inTown?40:P.z,   // down in the buried town: out of reach, like being in camp
  fa:P.fa,cy:S.carry==null?-1:S.carry,cr:!!P.crouch,hd:!!(P.crouch&&dep>0.95),dn:S.ko>0,nz:S.noise,hp:S.hp,an:P.anim,lt:!!S.light,kt:kateLoot(),on:S.onionT>0,vy:P.yaw}}
function stepSoloMonsters(dt){
  if(online())return;const ev=[];if(!ZONE_H&&hazOn('night'))SIM.stepMonsters(MONL,[meSim()],clockT(),dt,ev,{mood:RUN.mood});else{MONL.trucks=[];MONL.zer=null}   // police/Zeroni: lake only (88-zones.js)
  MONV.trucks=MONL.trucks.map(k=>({x:k.x,z:k.z,h:k.h,chase:k.mode==='chase'}));MONV.zer=MONL.zer?{x:MONL.zer.x,z:MONL.zer.z,tgt:MONL.zer.tgt,drag:MONL.zer.drag}:null;
  for(const e of ev)monEvent(e);
}
/* solo/offline event director (see public/director.js): online, the SERVER steps this and relays decisions
   through 'env' (server.js + the 'env' case in 65-net.js); here we run the identical logic locally and call
   spawnEnv() ourselves. Only when DIRECTOR_ON -- off falls back to the old per-cell twPlan/lsPlan schedules. */
function stepSoloDirector(dt){
  if(online()||!DIRECTOR_ON)return;
  if(!soloDirState)soloDirState=DIRECTOR.createState();
  const players=[{id:'me',x:P.x,z:P.z,inCamp:SIM.inCamp(P.x,P.z),down:S.ko>0}];
  const decisions=DIRECTOR.step(soloDirState,{now:Date.now(),day:RUN.day,players,clockT:clockT(),zone:ZONE.id,curse:RUN.curse||0,rate:tune('mon.events')});
  for(const d of decisions){
    if(!hazOn(d.kind))continue;   /* the hazards switch (88-hazards.js) */
    if(d.mode==='env')spawnEnv(d.kind,{x:d.x,z:d.z,a:d.a,dir:true});
    else if(d.kind==='javelinas'){const ev=[];SIM.spawnJavHerd(JAV_LOCAL,{x:P.x,z:P.z},SIM.JAV_COUNT,clamp(Math.hypot(d.x-P.x,d.z-P.z),50,100),ev);for(const e of ev)javEvent(e)}
    else if(d.kind==='lion')LIONL.pendingSpawn={x:d.x,z:d.z};   // solo: same monster starts the server does (see dirStartMonster in server.js)
  }
}
function monFromServer(m){
  MONV.trucks=(Array.isArray(m.trucks)?m.trucks:[]).slice(0,SIM.CURFEW_LIM.copN[1]).map(a=>({x:num(a[0],-700,700,0),z:num(a[1],-700,700,0),h:num(a[2],-1e4,1e4,0),chase:a[3]===1}));
  MONV.zer=Array.isArray(m.zer)?{x:num(m.zer[0],-700,700,0),z:num(m.zer[1],-700,700,0),tgt:m.zer[2],drag:m.zer[3]}:null;
  if(Array.isArray(m.ev))for(const e of m.ev.slice(0,20))if(e&&typeof e==='object')monEvent(e);
}
const COP_LINES=['Freeze!','Stop right there, camper!','Hands where I can see them!','Get back to camp, now!'];
function monEvent(e){
  const mine=e.id===myId();
  switch(e.k){
    case 'appeased':toast(`${e.by?cleanName(e.by)+' sang':'The crew sang'} Madame Zeroni the lullaby. She smiles, and fades away for the night. The curse eases.`,'gold',6500);sfx.gold();badge('lullaby');break;
    case 'spot':if(mine){toast('SPOTTED! Run for camp, or crouch (C) down in a deep hole.','bad',3000);tone(900,0.4,'square',0.06,1400);setTimeout(()=>tone(900,0.4,'square',0.06,1400),450);speak(pick(COP_LINES),{pitch:0.6,rate:1.15,vol:0.9,male:true})}break;
    case 'lost':if(mine&&performance.now()-CUR.msgT>8000){CUR.msgT=performance.now();toast('They lost you. For now.','',2500)}break;
    case 'down':if(mine&&!S.ko){if(e.by==='zeroni'){zeroniTalk(0);knockOut('Cursed','Madame Zeroni grabbed you and is dragging you away.')}else knockOut('Busted','The police caught you out on the lake after curfew.')}break;
    case 'talk':if(MONV.zer)zeroniTalk(Math.hypot(MONV.zer.x-P.x,MONV.zer.z-P.z));break;
    case 'blink':if(mine){zeroniSting(e.front?1.4:0.6);if(e.front)jumpScare()}break;
    case 'drop':if(mine&&S.ko)toast('Madame Zeroni let go of you.','good',2500);break;
    case 'gone':if(mine&&S.ko){S.ko=0.01;toast('Madame Zeroni dragged you off the edge of the lake. You wake up in the nurse\'s office.','bad',5000)}break;
    default:lionEvent(e);   // anything this switch doesn't know about is one of the mountain lion's events (see 85-lion.js)
  }
}

/* ================= co-op: team quota, levels, heavy loot, dropped sacks, helping friends, pings, chat, flashlights ================= */
function online(){return!!(net.ws&&net.ws.readyState===1)}
function othersOnline(){return online()&&remotes.size>0}
function dropLabel(L){L.el.remove();const i=labeled.indexOf(L);if(i>=0)labeled.splice(i,1)}
